static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.geometry = 1}) == VK_SHADER_STAGE_GEOMETRY_BIT);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.fragment = 1}) == VK_SHADER_STAGE_FRAGMENT_BIT);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.compute = 1}) == VK_SHADER_STAGE_COMPUTE_BIT);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.task = 1}) == VK_SHADER_STAGE_TASK_BIT_EXT);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.mesh = 1}) == VK_SHADER_STAGE_MESH_BIT_EXT);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.raygen = 1}) == VK_SHADER_STAGE_RAYGEN_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.any_hit = 1}) == VK_SHADER_STAGE_ANY_HIT_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.closest_hit = 1}) == VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.miss = 1}) == VK_SHADER_STAGE_MISS_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.intersection = 1}) == VK_SHADER_STAGE_INTERSECTION_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.callable = 1}) == VK_SHADER_STAGE_CALLABLE_BIT_KHR);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.subpass_shading = 1}) == VK_SHADER_STAGE_SUBPASS_SHADING_BIT_HUAWEI);
static_assert(::std::bit_cast<VkShaderStageFlags>(indirect_commands_layout::shader_stages_type{.cluster_culling = 1}) == VK_SHADER_STAGE_CLUSTER_CULLING_BIT_HUAWEI);
#endif

